+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL = Pattern.compile("[^\\s@]+@[^\\s@]+\\.[^\\s@]+");
+    private static final int MAX_MESSAGE_LENGTH = 500;
+
+    private final ContactMessages messages;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+    private final Dialog leaveDialog = new Dialog();
+
+    // Set while the form is cleared after a send, so that clearing does not count as an edit
+    private boolean clearing;
+    private BeforeLeaveEvent.ContinueNavigationAction pendingNavigation;
+
+    public ContactView(ContactMessages messages) {
+        this.messages = messages;
+
+        // Eager mode keeps the server's copy of the form in step with every keystroke
+        // (the leave guard and the Send button's enabled state depend on it)
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+
+        name.addValueChangeListener(e -> onEdit());
+        email.addValueChangeListener(e -> onEdit());
+        phone.addValueChangeListener(e -> onEdit());
+        message.addValueChangeListener(e -> onEdit());
+
+        sendButton.addClickListener(e -> submit());
+        sendButton.addClickShortcut(Key.ENTER);
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::email).setHeader("Email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        grid.addColumn(ContactMessage::message).setHeader("Message");
+
+        setUpLeaveDialog();
+
+        add(
+                new H1("Contact"),
+                new RouterLink("About", AboutView.class),
+                new FormLayout(name, email, phone, message),
+                sendButton,
+                grid,
+                leaveDialog);
+        refreshGrid();
+    }
+
+    private void onEdit() {
+        if (!clearing) {
+            sendButton.setEnabled(true);
+        }
+    }
+
+    private void submit() {
+        if (!validate()) {
+            return;
+        }
+        messages.add(new ContactMessage(
+                name.getValue().trim(),
+                email.getValue().trim(),
+                phone.getValue().trim(),
+                message.getValue().trim()));
+        refreshGrid();
+        Notification.show("Message sent");
+
+        clearing = true;
+        try {
+            name.clear();
+            email.clear();
+            phone.clear();
+            message.clear();
+        } finally {
+            clearing = false;
+        }
+        sendButton.setEnabled(false);
+    }
+
+    private boolean validate() {
+        String nameValue = name.getValue().trim();
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        String messageValue = message.getValue().trim();
+
+        String nameError = nameValue.isEmpty() ? "Name is required" : null;
+
+        String emailError = null;
+        if (!emailValue.isEmpty() && !EMAIL.matcher(emailValue).matches()) {
+            emailError = "Enter a valid e-mail address";
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            emailError = "Give an e-mail address or a phone number";
+        }
+
+        String messageError = null;
+        if (messageValue.isEmpty()) {
+            messageError = "Message is required";
+        } else if (messageValue.codePointCount(0, messageValue.length()) > MAX_MESSAGE_LENGTH) {
+            messageError = "Message must be at most 500 characters";
+        }
+
+        mark(name, nameError);
+        mark(email, emailError);
+        mark(message, messageError);
+        return nameError == null && emailError == null && messageError == null;
+    }
+
+    private static void mark(HasValidation field, String error) {
+        field.setInvalid(error != null);
+        field.setErrorMessage(error);
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messages.newestFirst());
+    }
+
+    private void setUpLeaveDialog() {
+        leaveDialog.setHeaderTitle("Discard your message?");
+        leaveDialog.add(new Paragraph("The message you are writing has not been sent. Leaving now loses it."));
+
+        Button keepEditing = new Button("Keep editing", e -> keepEditing());
+        Button discard = new Button("Discard", e -> discard());
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        leaveDialog.getFooter().add(keepEditing, discard);
+
+        leaveDialog.setCloseOnEsc(false);
+        leaveDialog.setCloseOnOutsideClick(false);
+    }
+
+    private void keepEditing() {
+        pendingNavigation = null;
+        leaveDialog.close();
+    }
+
+    private void discard() {
+        leaveDialog.close();
+        BeforeLeaveEvent.ContinueNavigationAction action = pendingNavigation;
+        pendingNavigation = null;
+        if (action != null) {
+            action.proceed();
+        }
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasUnsentInput()) {
+            pendingNavigation = event.postpone();
+            leaveDialog.open();
+        }
+    }
+
+    private boolean hasUnsentInput() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+}
