+package com.example.contact;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+import static org.springframework.boot.test.context.SpringBootTest.WebEnvironment.RANDOM_PORT;
+
+import java.util.UUID;
+
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+
+@SpringBootTest(webEnvironment = RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    private void openContact() {
+        page.navigate(getUrl() + "/contact");
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+    }
+
+    private Locator field(String label) {
+        return page.getByLabel(label, new Page.GetByLabelOptions().setExact(true));
+    }
+
+    private Locator send() {
+        return page.locator("vaadin-button", new Page.LocatorOptions().setHasText("Send"));
+    }
+
+    private Locator aboutLink() {
+        return page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About"));
+    }
+
+    private Locator heading() {
+        return page.locator("h1").first();
+    }
+
+    @Test
+    void sendingWithEnterListsTheMessageAndClearsTheForm() {
+        openContact();
+        String name = "Browser " + UUID.randomUUID();
+        field("Name").fill(name);
+        field("Email").fill("browser@example.com");
+        field("Message").fill("Hello from the browser");
+
+        field("Message").press("Enter");
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        assertThat(page.locator("vaadin-grid-cell-content")
+                .filter(new Locator.FilterOptions().setHasText(name))).hasCount(1);
+        assertThat(page.getByText("Hello from the browser")).isVisible();
+        assertThat(field("Name")).hasValue("");
+        assertThat(field("Message")).hasValue("");
+        assertThat(send()).isDisabled();
+
+        field("Phone").pressSequentially("1");
+
+        assertThat(send()).isEnabled();
+    }
+
+    @Test
+    void invalidSubmitShowsEveryErrorAndSendsNothing() {
+        openContact();
+
+        send().click();
+
+        assertThat(page.getByText("Name is required")).isVisible();
+        assertThat(page.getByText("Give an e-mail address or a phone number")).isVisible();
+        assertThat(page.getByText("Message is required")).isVisible();
+        assertThat(page.getByText("Message sent")).hasCount(0);
+    }
+
+    @Test
+    void leavingWithTypedInputAsksFirstAndKeepEditingStays() {
+        openContact();
+        field("Name").fill("Unsent");
+
+        aboutLink().click();
+
+        assertThat(page.getByText("Discard your message?")).isVisible();
+        assertThat(heading()).hasText("Contact");
+
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing").setExact(true)).click();
+
+        assertThat(page.getByText("Discard your message?")).isHidden();
+        assertThat(heading()).hasText("Contact");
+        assertThat(field("Name")).hasValue("Unsent");
+    }
+
+    @Test
+    void discardLeavesTheContactView() {
+        openContact();
+        field("Name").fill("Unsent");
+        aboutLink().click();
+
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard").setExact(true)).click();
+
+        assertThat(heading()).hasText("About");
+    }
+
+    @Test
+    void leavingAnEmptyFormIsNotInterrupted() {
+        openContact();
+
+        aboutLink().click();
+
+        assertThat(heading()).hasText("About");
+        assertThat(page.getByText("Discard your message?")).hasCount(0);
+    }
+}
