+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.UUID;
+
+import com.example.about.AboutView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name() {
+        return $(TextField.class).withLabel("Name").single();
+    }
+
+    private EmailField email() {
+        return $(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextField phone() {
+        return $(TextField.class).withLabel("Phone").single();
+    }
+
+    private TextArea message() {
+        return $(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button send() {
+        return $(Button.class).withText("Send").single();
+    }
+
+    private Grid<ContactMessage> grid() {
+        @SuppressWarnings("unchecked")
+        Grid<ContactMessage> grid = (Grid<ContactMessage>) $(Grid.class).single();
+        return grid;
+    }
+
+    private void fillValid(String name) {
+        name().setValue(name);
+        email().setValue(name.toLowerCase() + "@example.com");
+        message().setValue("Hello from " + name);
+    }
+
+    private static String uniqueName() {
+        return "tester-" + UUID.randomUUID();
+    }
+
+    private boolean notificationShown(String text) {
+        return find(Notification.class).all().stream()
+                .anyMatch(n -> n.isOpened() && n.getElement().getProperty("text", "").contains(text));
+    }
+
+    @Test
+    void viewHasHeadingFieldsAndEnabledSendButton() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertTrue(name().isEmpty());
+        assertTrue(email().isEmpty());
+        assertTrue(phone().isEmpty());
+        assertTrue(message().isEmpty());
+        assertTrue(send().isEnabled());
+        assertInstanceOf(Grid.class, $(Grid.class).single());
+    }
+
+    @Test
+    void emptyFormMarksEachRequiredFieldAndSendsNothing() {
+        navigate(ContactView.class);
+        int before = grid().getListDataView().getItems().toList().size();
+
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertEquals(before, grid().getListDataView().getItems().toList().size());
+        assertFalse(notificationShown("Message sent"));
+    }
+
+    @Test
+    void malformedEmailIsRejectedAndTypedValuesStay() {
+        navigate(ContactView.class);
+        name().setValue("Ada");
+        email().setValue("not-an-address");
+        message().setValue("Hi");
+
+        test(send()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertFalse(name().isInvalid());
+        assertEquals("Ada", name().getValue());
+        assertEquals("Hi", message().getValue());
+    }
+
+    @Test
+    void messageLongerThan500CharactersIsRejected() {
+        navigate(ContactView.class);
+        fillValid(uniqueName());
+        message().setValue("x".repeat(501));
+
+        test(send()).click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+    }
+
+    @Test
+    void messageOf500CharactersIsAccepted() {
+        navigate(ContactView.class);
+        String name = uniqueName();
+        fillValid(name);
+        message().setValue("x".repeat(500));
+
+        test(send()).click();
+
+        assertFalse(message().isInvalid());
+        assertEquals(name, grid().getListDataView().getItems().findFirst().orElseThrow().name());
+    }
+
+    @Test
+    void phoneAloneIsEnoughWithoutEmail() {
+        navigate(ContactView.class);
+        String name = uniqueName();
+        name().setValue(name);
+        phone().setValue("+358 40 123 4567");
+        message().setValue("Call me");
+
+        test(send()).click();
+
+        assertFalse(email().isInvalid());
+        assertEquals(name, grid().getListDataView().getItems().findFirst().orElseThrow().name());
+    }
+
+    @Test
+    void validSendAddsNewestFirstClearsFormAndDisablesSend() {
+        navigate(ContactView.class);
+        String name = uniqueName();
+        fillValid(name);
+
+        test(send()).click();
+
+        assertTrue(notificationShown("Message sent"));
+        assertEquals(name, grid().getListDataView().getItems().findFirst().orElseThrow().name());
+        assertEquals("Hello from " + name,
+                grid().getListDataView().getItems().findFirst().orElseThrow().message());
+        assertTrue(name().isEmpty());
+        assertTrue(email().isEmpty());
+        assertTrue(phone().isEmpty());
+        assertTrue(message().isEmpty());
+        assertFalse(send().isEnabled());
+    }
+
+    @Test
+    void editingAfterSendReEnablesSend() {
+        navigate(ContactView.class);
+        fillValid(uniqueName());
+        test(send()).click();
+        assertFalse(send().isEnabled());
+
+        name().setValue("Again");
+
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void enterSendsTheMessage() {
+        navigate(ContactView.class);
+        String name = uniqueName();
+        fillValid(name);
+
+        fireShortcut(Key.ENTER);
+
+        assertTrue(notificationShown("Message sent"));
+        assertEquals(name, grid().getListDataView().getItems().findFirst().orElseThrow().name());
+    }
+
+    @Test
+    void enterDoesNothingWhileSendIsDisabled() {
+        navigate(ContactView.class);
+        fillValid(uniqueName());
+        test(send()).click();
+        int before = grid().getListDataView().getItems().toList().size();
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(before, grid().getListDataView().getItems().toList().size());
+        assertTrue(name().isEmpty());
+    }
+
+    @Test
+    void sentMessagesAreStillListedAfterRevisiting() {
+        navigate(ContactView.class);
+        String name = uniqueName();
+        fillValid(name);
+        test(send()).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        assertEquals(name, grid().getListDataView().getItems().findFirst().orElseThrow().name());
+    }
+
+    @Test
+    void leavingWithTypedInputAsksFirstAndKeepEditingStays() {
+        navigate(ContactView.class);
+        name().setValue("Unsent");
+
+        UI.getCurrent().navigate(AboutView.class);
+
+        Dialog dialog = $(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        test($(Button.class).withText("Keep editing").single()).click();
+
+        assertFalse(dialog.isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Unsent", name().getValue());
+    }
+
+    @Test
+    void discardLeavesTheView() {
+        navigate(ContactView.class);
+        name().setValue("Unsent");
+        UI.getCurrent().navigate(AboutView.class);
+
+        test($(Button.class).withText("Discard").single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void leavingAnEmptyFormIsNotInterrupted() {
+        navigate(ContactView.class);
+
+        navigate(AboutView.class);
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertTrue($(Dialog.class).all().stream().noneMatch(Dialog::isOpened));
+    }
+}
